cat > /tmp/whatwg.mjs <<'EOF'
// Independent UTF-8 decoder written from the WHATWG Encoding spec's state machine.
// WHATWG and CPython accept exactly the same well-formed sequences and resume at
// the same byte after an error (spec: "prepend byte to stream"; CPython:
// endinpos = start + maximal-subpart), so the token stream below is a valid
// oracle for CPython's maximal-subpart boundaries.
export function whatwgTokens(buf) {
  const toks = [];           // {cp} | {errBytes:[...]}
  let cp = 0, seen = 0, needed = 0, lower = 0x80, upper = 0xbf;
  let pending = [];          // bytes consumed into the current partial sequence
  let i = 0;
  while (i <= buf.length) {
    if (i === buf.length) {           // end of queue
      if (needed !== 0) { toks.push({ errBytes: pending.slice() }); }
      break;
    }
    const byte = buf[i];
    if (needed === 0) {
      if (byte <= 0x7f) { toks.push({ cp: byte }); i++; continue; }
      if (byte >= 0xc2 && byte <= 0xdf) { needed = 1; cp = byte & 0x1f; }
      else if (byte >= 0xe0 && byte <= 0xef) {
        if (byte === 0xe0) lower = 0xa0;
        if (byte === 0xed) upper = 0x9f;
        needed = 2; cp = byte & 0x0f;
      } else if (byte >= 0xf0 && byte <= 0xf4) {
        if (byte === 0xf0) lower = 0x90;
        if (byte === 0xf4) upper = 0x8f;
        needed = 3; cp = byte & 0x07;
      } else { toks.push({ errBytes: [byte] }); i++; continue; }
      pending = [byte]; i++; continue;
    }
    if (byte < lower || byte > upper) {
      toks.push({ errBytes: pending.slice() });   // offending byte is prepended back
      cp = 0; seen = 0; needed = 0; lower = 0x80; upper = 0xbf; pending = [];
      continue;                                   // reprocess same i
    }
    lower = 0x80; upper = 0xbf;
    cp = (cp << 6) | (byte & 0x3f);
    pending.push(byte); seen++; i++;
    if (seen === needed) {
      toks.push({ cp });
      cp = 0; seen = 0; needed = 0; pending = [];
    }
  }
  return toks;
}

/** Flatten oracle tokens into the code-point sequence CPython's surrogateescape gives. */
export function oracleCodePoints(buf) {
  const out = [];
  for (const t of whatwgTokens(buf)) {
    if ('cp' in t) out.push(t.cp);
    else for (const b of t.errBytes) out.push(0xdc00 + b);
  }
  return out;
}
