import { decodeSurrogateEscape } from '/output/lib/pyunicode.mjs';
import { oracleCodePoints } from '/tmp/whatwg.mjs';

function actualCodePoints(buf) {
  const s = decodeSurrogateEscape(buf);
  // Interpret as Python code points: lone low surrogates stay lone; pairs combine.
  const out = [];
  for (let i = 0; i < s.length; i++) {
    const u = s.charCodeAt(i);
    if (u >= 0xd800 && u <= 0xdbff && i + 1 < s.length) {
      const v = s.charCodeAt(i + 1);
      if (v >= 0xdc00 && v <= 0xdfff) { out.push(((u - 0xd800) << 10) + (v - 0xdc00) + 0x10000); i++; continue; }
    }
    out.push(u);
  }
  return out;
}
let bad = 0, n = 0;
function test(buf) {
  n++;
  const a = actualCodePoints(buf), b = oracleCodePoints(buf);
  if (a.length !== b.length || a.some((x, k) => x !== b[k])) {
    if (bad < 20) console.log('MISMATCH', Buffer.from(buf).toString('hex'),
      '\n  got     ', a.map(c=>c.toString(16)).join(' '),
      '\n  expected', b.map(c=>c.toString(16)).join(' '));
    bad++;
  }
}
// exhaustive lengths 1..2 over all 256 byte values
for (let a = 0; a < 256; a++) { test([a]); for (let b = 0; b < 256; b++) test([a, b]); }
// exhaustive lengths 3..4 over a boundary-complete alphabet
const AL = [0x00,0x41,0x7f,0x80,0x8f,0x90,0x9f,0xa0,0xbf,0xc0,0xc1,0xc2,0xdf,0xe0,0xe1,0xec,0xed,0xee,0xef,0xf0,0xf1,0xf3,0xf4,0xf5,0xff];
for (const a of AL) for (const b of AL) for (const c of AL) { test([a,b,c]); for (const d of AL) test([a,b,c,d]); }
// length 5 random over full range
let seed=1;const rnd=()=>{seed=(seed*1103515245+12345)&0x7fffffff;return seed;};
for(let k=0;k<400000;k++) test(Array.from({length:5},()=>rnd()%256));
console.log(`decoder: ${n-bad}/${n} match independent WHATWG-derived oracle`);
